import json,struct,math,hashlib
from pathlib import Path
root=Path(__file__).resolve().parent
pack=lambda x:struct.pack('<'+'f'*len(x),*x)
summary={'scope':'Single ordinary120step fresh-history replays; no physical acceptance or five-repeat qualification','cases':{}}
for case,target in [('hip',3943),('severe',5004)]:
 initial={int(s[1]):list(map(float,s[2:15])) for s in map(str.split,(root/f'{case}-initial.txt').read_text().splitlines())}
 results={}
 for arm in ['baseline','candidate']:
  out=root/f'{case}-{arm}';assert json.loads((out/'exit.json').read_text())['exit']==0
  lines=list(map(str.split,(out/'run.log').read_text().splitlines()))
  getters={int(t[1]):list(map(float,t[2:])) for t in lines if t and t[0]=='replay-initial'}
  assert set(getters)==set(initial) and all(pack(getters[k])==pack(initial[k]) for k in initial)
  frames={};anchor=0;target_anchor=0;omega=0
  for t in map(str.split,(out/'state.txt').read_text().splitlines()):
   f,k=map(int,t[:2]);x=list(map(float,t[2:]));assert len(x)==14 and all(map(math.isfinite,x));assert k not in frames.setdefault(f,{})
   frames[f][k]=x;anchor=max(anchor,x[13]);omega=max(omega,math.sqrt(sum(v*v for v in x[10:13])))
   if k==target:target_anchor=max(target_anchor,x[13])
  assert sorted(frames)==list(range(120)) and all(set(v)==set(initial) for v in frames.values())
  limits=[dict(frame=int(t[1]),body=int(t[2]),cone=float(t[6]),lower=float(t[11]),upper=float(t[12])) for t in lines if t and t[0]=='replay-spherical-limit']
  assert len(limits)==3240 and len(set((v['frame'],v['body']) for v in limits))==3240
  limit_frames={f:{v['body'] for v in limits if v['frame']==f} for f in range(120)}
  assert set(v['frame'] for v in limits)==set(range(120))
  assert len(limit_frames[0])==27 and limit_frames[0].issubset(initial)
  assert all(ids==limit_frames[0] for ids in limit_frames.values())
  assert all(math.isfinite(v[k]) for v in limits for k in ['cone','lower','upper'])
  targeted=[v for v in limits if v['body']==target];assert len(targeted)==120
  peak=lambda a:{k:max(v[k] for v in a) for k in ['cone','lower','upper']}
  results[arm]=dict(frames=120,body_observations=5040,spherical_observations=3240,initial_exact=True,peak_anchor_all=anchor,peak_anchor_target=target_anchor,peak_omega_all=omega,all_joint_peaks=peak(limits),target_peaks=peak(targeted),target_tail60_peaks=peak([v for v in targeted if v['frame']>=60]),target_final=targeted[-1],sha256={f:hashlib.sha256((out/f).read_bytes()).hexdigest() for f in ['manifest.json','state.txt','run.log','exit.json']})
  print(case,arm,json.dumps({k:v for k,v in results[arm].items() if k!='sha256'}),flush=True)
 summary['cases'][case]=results
(root/'summary.json').write_text(json.dumps(summary,indent=2))

